local HarrowMaker = {}
local PRODUCTS = {
    simple_wood_harrow = { name = "Preprosto leseno brano", woodCost = 3, ironCost = 1, time = 3, cost = 60, food = 12, happiness = 1, description = "Preprosto leseno brano za razbijanje grud." },
    iron_tooth_harrow = { name = "Železnozoba brano", woodCost = 3, ironCost = 2, time = 5, cost = 180, food = 22, happiness = 1, prestige = 2, description = "Železnozoba brano za trgovce." },
    steel_spiked_harrow = { name = "Jeklenobodena brano", woodCost = 3, ironCost = 2, steelCost = 1, time = 8, cost = 440, food = 35, happiness = 2, prestige = 6, description = "Jeklenobodena brano za plemiče." },
    silver_trimmed_harrow = { name = "Srebrnoobrobljena brano", woodCost = 3, ironCost = 2, silverCost = 1, steelCost = 1, time = 12, cost = 1100, food = 48, happiness = 3, prestige = 14, description = "Srebrnoobrobljena brano za visoke plemiče." },
    gold_trimmed_harrow = { name = "Zlatookrasna brano", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, jewelCost = 1, time = 16, cost = 2400, food = 62, happiness = 5, prestige = 27, description = "Brano z draguljem za visoko plemstvo." },
    royal_grand_harrow = { name = "Kraljevski veliki brano", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 5200, food = 82, happiness = 12, prestige = 58, description = "Veliki kraljevski brano z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    harrow_workshop = { name = "Branska delavnica", cost = { gold = 240, wood = 160, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 880, wood = 320, stone = 240, silver = 6, steel = 4 }, upkeep = 20, qualityBonus = 18 },
    master_harrow_atelier = { name = "Mojstrski branski atelje", cost = { gold = 2500, wood = 380, stone = 520, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
HarrowMaker.woodStock = 18; HarrowMaker.ironStock = 14; HarrowMaker.steelStock = 8; HarrowMaker.silverStock = 6; HarrowMaker.goldStock = 6; HarrowMaker.jewelStock = 4; HarrowMaker.pearlStock = 4
HarrowMaker.productStock = {}; HarrowMaker.buildings = {}; HarrowMaker.maker = nil; HarrowMaker.activeMaking = {}; HarrowMaker.totalProducts = 0; HarrowMaker.dayTimer = 0
function HarrowMaker.init() HarrowMaker.woodStock=18; HarrowMaker.ironStock=14; HarrowMaker.steelStock=8; HarrowMaker.silverStock=6; HarrowMaker.goldStock=6; HarrowMaker.jewelStock=4; HarrowMaker.pearlStock=4; HarrowMaker.productStock={}; HarrowMaker.buildings={}; HarrowMaker.maker=nil; HarrowMaker.activeMaking={}; HarrowMaker.totalProducts=0; HarrowMaker.dayTimer=0; print("[HarrowMaker] Royal Harrow Maker System initialized (6 products, 4 buildings)") end
function HarrowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HarrowMaker.maker={name=n or ("Bransar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bransar najet: %s (spretnost: %d)",HarrowMaker.maker.name,s),"success") end; return true end
function HarrowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HarrowMaker.build(id) local ok,e=HarrowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HarrowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HarrowMaker.getQualityBonus() local b=0; for _,bd in ipairs(HarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HarrowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and HarrowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and HarrowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and HarrowMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and HarrowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HarrowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HarrowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HarrowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HarrowMaker.buildings==0 then return false,"Potrebna branska delavnica" end; if not HarrowMaker.maker then return false,"Potreben bransar" end; return true end
function HarrowMaker.make(pt,qty) qty=qty or 1; local ok,e=HarrowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then HarrowMaker.woodStock=HarrowMaker.woodStock-d.woodCost*qty end; if d.ironCost then HarrowMaker.ironStock=HarrowMaker.ironStock-d.ironCost*qty end; if d.steelCost then HarrowMaker.steelStock=HarrowMaker.steelStock-d.steelCost*qty end; if d.silverCost then HarrowMaker.silverStock=HarrowMaker.silverStock-d.silverCost*qty end; if d.goldCost then HarrowMaker.goldStock=HarrowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HarrowMaker.jewelStock=HarrowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HarrowMaker.pearlStock=HarrowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HarrowMaker.maker then t=math.max(1,t-math.floor(HarrowMaker.maker.skill/14)) end; table.insert(HarrowMaker.activeMaking,{id="harrow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HarrowMaker.completeMaking(m) local q=1.0+(HarrowMaker.getQualityBonus()/100); if HarrowMaker.maker then q=q+(HarrowMaker.maker.skill/140) end; q=math.min(2.5,q); HarrowMaker.productStock[m.productType]=(HarrowMaker.productStock[m.productType] or 0)+m.quantity; HarrowMaker.totalProducts=HarrowMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HarrowMaker.maker then HarrowMaker.maker.itemsMade=HarrowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HarrowMaker.maker.skill=math.min(100,HarrowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brano izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"harrow.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function HarrowMaker.update(dt) if not _G.state then return end; HarrowMaker.dayTimer=HarrowMaker.dayTimer+dt; if HarrowMaker.dayTimer>=30 then HarrowMaker.dayTimer=0; for i=#HarrowMaker.activeMaking,1,-1 do local m=HarrowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HarrowMaker.completeMaking(m); table.remove(HarrowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HarrowMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HarrowMaker.getStats() return {woodStock=HarrowMaker.woodStock,ironStock=HarrowMaker.ironStock,steelStock=HarrowMaker.steelStock,silverStock=HarrowMaker.silverStock,goldStock=HarrowMaker.goldStock,jewelStock=HarrowMaker.jewelStock,pearlStock=HarrowMaker.pearlStock,productStock=HarrowMaker.productStock,numBuildings=#HarrowMaker.buildings,hasMaker=HarrowMaker.maker~=nil,makerName=HarrowMaker.maker and HarrowMaker.maker.name or "—",makerSkill=HarrowMaker.maker and HarrowMaker.maker.skill or 0,activeMaking=#HarrowMaker.activeMaking,totalProducts=HarrowMaker.totalProducts} end
return HarrowMaker
